-- Partial unique indexes and the composite/BRIN indexes that carry the
-- documented access patterns. Simple single-column indexes were generated by
-- Drizzle in 0000_r1_schema.sql; these are the expressions that Drizzle's
-- table builder cannot express cleanly.

-- Identity and reference data ------------------------------------------------

CREATE UNIQUE INDEX IF NOT EXISTS "uq_users_email_lower"
  ON "users" (lower("email"));

CREATE UNIQUE INDEX IF NOT EXISTS "uq_instruments_exchange_symbol_active"
  ON "instruments" ("exchange_id", "trading_symbol") WHERE "is_active";

CREATE UNIQUE INDEX IF NOT EXISTS "uq_instrument_provider_primary"
  ON "instrument_provider_mappings" ("instrument_id", "provider_id") WHERE "is_primary";

CREATE INDEX IF NOT EXISTS "idx_instruments_segment_active"
  ON "instruments" ("segment", "is_active");

CREATE INDEX IF NOT EXISTS "idx_corporate_actions_instrument_date"
  ON "corporate_actions" ("instrument_id", "ex_date");

CREATE INDEX IF NOT EXISTS "idx_corporate_actions_exdate_type"
  ON "corporate_actions" ("ex_date", "action_type");

CREATE INDEX IF NOT EXISTS "idx_trading_calendar_date_open"
  ON "trading_calendar" ("trading_date", "is_trading_day");

CREATE INDEX IF NOT EXISTS "idx_instrument_universe_versions_effective"
  ON "instrument_universe_versions" ("universe_id", "effective_from");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_instrument_universe_versions_open"
  ON "instrument_universe_versions" ("universe_id") WHERE "effective_to" IS NULL;

CREATE INDEX IF NOT EXISTS "idx_instrument_universe_members_instrument"
  ON "instrument_universe_members" ("instrument_id");

-- Provider payloads and ingestion -------------------------------------------

CREATE INDEX IF NOT EXISTS "idx_raw_payloads_provider_endpoint_time"
  ON "raw_provider_payloads" ("provider_id", "endpoint", "fetched_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_ingestion_runs_status_started"
  ON "market_data_ingestion_runs" ("status", "started_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_ingestion_runs_provider_type_time"
  ON "market_data_ingestion_runs" ("provider_id", "run_type", "created_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_ingestion_runs_instrument_window"
  ON "market_data_ingestion_runs" ("instrument_id", "requested_from", "requested_to");

CREATE INDEX IF NOT EXISTS "idx_data_quality_open"
  ON "data_quality_issues" ("severity", "detected_at" DESC) WHERE "status" = 'open';

CREATE INDEX IF NOT EXISTS "idx_data_quality_instrument_date"
  ON "data_quality_issues" ("instrument_id", "trading_date");

CREATE INDEX IF NOT EXISTS "idx_data_quality_status_severity"
  ON "data_quality_issues" ("status", "severity");

-- Account and access ---------------------------------------------------------

CREATE INDEX IF NOT EXISTS "idx_accounts_active_mode"
  ON "accounts" ("is_active", "mode");

CREATE INDEX IF NOT EXISTS "idx_user_sessions_user_expires"
  ON "user_sessions" ("user_id", "expires_at");

CREATE INDEX IF NOT EXISTS "idx_user_account_access_active"
  ON "user_account_access" ("user_id", "account_id") WHERE "expires_at" IS NULL;

CREATE INDEX IF NOT EXISTS "idx_broker_credentials_expiry"
  ON "broker_credentials" ("expires_at") WHERE "expires_at" IS NOT NULL;

CREATE INDEX IF NOT EXISTS "idx_broker_credentials_provider"
  ON "broker_credentials" ("provider_id");

CREATE INDEX IF NOT EXISTS "idx_account_instrument_active"
  ON "account_instrument_permissions" ("account_id", "instrument_id") WHERE "effective_to" IS NULL;

-- The permission version must be unique per account, instrument and start date.
CREATE UNIQUE INDEX IF NOT EXISTS "uq_account_instrument_effective"
  ON "account_instrument_permissions" ("account_id", "instrument_id", "effective_from");

-- Configuration and strategy -------------------------------------------------

CREATE INDEX IF NOT EXISTS "idx_configuration_versions_effective"
  ON "configuration_versions" ("config_type", "scope_key", "effective_from" DESC);

CREATE INDEX IF NOT EXISTS "idx_strategy_config_bindings_config"
  ON "strategy_config_bindings" ("configuration_version_id");

CREATE INDEX IF NOT EXISTS "idx_strategy_universe_members_strategy"
  ON "strategy_universe_members" ("strategy_version_id");

CREATE INDEX IF NOT EXISTS "idx_strategy_activations_account_status"
  ON "strategy_activations" ("account_id", "status");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_strategy_activations_active"
  ON "strategy_activations" ("strategy_version_id", "account_id", "mode") WHERE "status" = 'active';

CREATE INDEX IF NOT EXISTS "idx_trading_sessions_date_status"
  ON "trading_sessions" ("trading_date", "status");

CREATE INDEX IF NOT EXISTS "idx_trading_sessions_account_date"
  ON "trading_sessions" ("account_id", "trading_date");

-- Execution ------------------------------------------------------------------

CREATE INDEX IF NOT EXISTS "idx_round_trip_trades_strategy_exit"
  ON "round_trip_trades" ("strategy_version_id", "exit_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_round_trip_trades_account_entry"
  ON "round_trip_trades" ("account_id", "entry_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_round_trip_trades_instrument"
  ON "round_trip_trades" ("instrument_id");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_positions_open"
  ON "positions" ("account_id", "instrument_id", "product") WHERE "status" = 'open';

CREATE INDEX IF NOT EXISTS "idx_positions_account_status"
  ON "positions" ("account_id", "status");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_orders_account_broker"
  ON "orders" ("account_id", "broker_order_id") WHERE "broker_order_id" IS NOT NULL;

CREATE INDEX IF NOT EXISTS "idx_orders_account_session_status"
  ON "orders" ("account_id", "trading_session_id", "status");

CREATE INDEX IF NOT EXISTS "idx_orders_instrument_time"
  ON "orders" ("instrument_id", "placed_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_orders_status_time"
  ON "orders" ("status", "placed_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_order_events_order_time"
  ON "order_events" ("order_id", "occurred_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_order_events_occurred_brin"
  ON "order_events" USING brin ("occurred_at");

CREATE INDEX IF NOT EXISTS "idx_position_events_position_time"
  ON "position_events" ("position_id", "occurred_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_fills_instrument_time"
  ON "fills" ("instrument_id", "executed_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_trade_costs_model"
  ON "trade_costs" ("cost_model_version");

CREATE INDEX IF NOT EXISTS "idx_risk_events_session_time"
  ON "risk_events" ("trading_session_id", "occurred_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_risk_events_unresolved"
  ON "risk_events" ("severity", "occurred_at" DESC) WHERE "resolved_at" IS NULL;

CREATE INDEX IF NOT EXISTS "idx_risk_events_type_time"
  ON "risk_events" ("event_type", "occurred_at" DESC);

-- Reconciliation snapshots ---------------------------------------------------

CREATE UNIQUE INDEX IF NOT EXISTS "uq_broker_positions_snapshot"
  ON "broker_position_snapshots" ("account_id", "instrument_id", "product", "captured_at");

CREATE INDEX IF NOT EXISTS "idx_broker_positions_account_time"
  ON "broker_position_snapshots" ("account_id", "captured_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_broker_positions_date"
  ON "broker_position_snapshots" ("trading_date");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_holdings_snapshot"
  ON "holdings_snapshots" ("account_id", "instrument_id", "captured_at");

CREATE INDEX IF NOT EXISTS "idx_holdings_account_time"
  ON "holdings_snapshots" ("account_id", "captured_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_holdings_isin"
  ON "holdings_snapshots" ("isin");

CREATE UNIQUE INDEX IF NOT EXISTS "uq_account_equity_snapshot"
  ON "account_equity_snapshots" ("account_id", "captured_at");

CREATE INDEX IF NOT EXISTS "idx_account_equity_date_type"
  ON "account_equity_snapshots" ("trading_date", "snapshot_type");

CREATE INDEX IF NOT EXISTS "idx_account_equity_account_time"
  ON "account_equity_snapshots" ("account_id", "captured_at" DESC);

-- Backtesting ----------------------------------------------------------------

CREATE INDEX IF NOT EXISTS "idx_backtest_runs_strategy_started"
  ON "backtest_runs" ("strategy_version_id", "created_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_backtest_runs_status"
  ON "backtest_runs" ("status");

CREATE INDEX IF NOT EXISTS "idx_backtest_runs_dataset"
  ON "backtest_runs" ("dataset_from", "dataset_to");

CREATE INDEX IF NOT EXISTS "idx_backtest_trades_run_entry"
  ON "backtest_trades" ("backtest_run_id", "entry_at");

CREATE INDEX IF NOT EXISTS "idx_backtest_trades_run_instrument"
  ON "backtest_trades" ("backtest_run_id", "instrument_id");

CREATE INDEX IF NOT EXISTS "idx_backtest_trades_window"
  ON "backtest_trades" ("window_id");

CREATE INDEX IF NOT EXISTS "idx_promotion_reviews_strategy_time"
  ON "strategy_promotion_reviews" ("strategy_version_id", "reviewed_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_promotion_reviews_status"
  ON "strategy_promotion_reviews" ("status");

CREATE INDEX IF NOT EXISTS "idx_promotion_reviews_run"
  ON "strategy_promotion_reviews" ("backtest_run_id");

-- Operations -----------------------------------------------------------------

CREATE INDEX IF NOT EXISTS "idx_daily_performance_date"
  ON "daily_performance" ("trading_date");

CREATE INDEX IF NOT EXISTS "idx_strategy_performance_strategy_date"
  ON "strategy_performance_daily" ("strategy_version_id", "trading_date");

CREATE INDEX IF NOT EXISTS "idx_strategy_performance_account_date"
  ON "strategy_performance_daily" ("account_id", "trading_date");

CREATE INDEX IF NOT EXISTS "idx_job_runs_status_scheduled"
  ON "job_runs" ("status", "scheduled_for");

CREATE INDEX IF NOT EXISTS "idx_job_runs_name_started"
  ON "job_runs" ("job_name", "started_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_health_component_time"
  ON "system_health_snapshots" ("component", "captured_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_health_status_time"
  ON "system_health_snapshots" ("status", "captured_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_health_captured_brin"
  ON "system_health_snapshots" USING brin ("captured_at");

CREATE INDEX IF NOT EXISTS "idx_notifications_status_time"
  ON "notification_events" ("status", "created_at");

CREATE INDEX IF NOT EXISTS "idx_notifications_severity_time"
  ON "notification_events" ("severity", "created_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_notifications_entity"
  ON "notification_events" ("related_entity_type", "related_entity_id");

CREATE INDEX IF NOT EXISTS "idx_report_runs_type_period"
  ON "report_runs" ("report_type", "period_start" DESC);

CREATE INDEX IF NOT EXISTS "idx_report_runs_status"
  ON "report_runs" ("status");

-- Audit and outbox -----------------------------------------------------------

CREATE INDEX IF NOT EXISTS "idx_audit_log_entity_time"
  ON "audit_log" ("entity_type", "entity_id", "created_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_audit_log_actor_time"
  ON "audit_log" ("actor_user_id", "created_at" DESC);

CREATE INDEX IF NOT EXISTS "idx_audit_log_created_brin"
  ON "audit_log" USING brin ("created_at");

CREATE INDEX IF NOT EXISTS "idx_domain_events_unpublished"
  ON "domain_events" ("occurred_at") WHERE "published_at" IS NULL;

CREATE INDEX IF NOT EXISTS "idx_domain_events_aggregate"
  ON "domain_events" ("aggregate_type", "aggregate_id", "occurred_at");

CREATE INDEX IF NOT EXISTS "idx_domain_events_type_time"
  ON "domain_events" ("event_type", "occurred_at");
